      de: ["Es ist die größte Süßwasserlagune im Departement Maldonado.", "Die Fläche beträgt ungefähr 5.500 Hektar (55 km²).", "Die maximale Tiefe beträgt 14 Meter.", "Sie liefert Trinkwasser für über 150.000 Menschen.", "Ihr Name bedeutet 'Weidenlagune'.", "Der internationale Flughafen von Punta del Este (Laguna del Sauce) liegt an ihrem Ufer."],
      hu: ["Ez Maldonado megye legnagyobb édesvizű lagúnája.", "Területe körülbelül 5500 hektár (55 km²).", "Maximális mélysége 14 méter.", "Több mint 150 000 ember ivóvizét biztosítja.", "Neve 'Fűzfa-lagúnát' jelent.", "A partján fekszik a Punta del Este-i nemzetközi repülőtér (Laguna del Sauce)."],
      ro: ["Este cea mai mare lagună de apă dulce din departamentul Maldonado.", "Suprafața sa este de aproximativ 5.500 de hectare (55 km²).", "Adâncimea sa maximă este de 14 metri.", "Furnizează apă potabilă pentru peste 150.000 de persoane.", "Numele său înseamnă 'Laguna Salciei'.", "Aeroportul Internațional Punta del Este (Laguna del Sauce) este situat pe malul său."],
      en: ["It is the largest freshwater lagoon in the Maldonado department.", "Its surface area is approximately 5,500 hectares (55 km²).", "Its maximum depth is 14 meters.", "It provides drinking water to over 150,000 people.", "Its name means 'Lagoon of the Willow'.", "Punta del Este's international airport (Laguna del Sauce) is located on its shore."],
      es: ["Hábitat importante para la fauna y flora de Uruguay.", "Popular para caminatas por la naturaleza y observación de aves.", "Papel importante en el ciclo regional del agua.", "Está parcialmente bajo protección estatal.", "El sitio es parte del patrimonio nacional de Uruguay y se incluye en materiales educativos."],
