      es: ["Famosa por su puente de forma circular.", "Parte de una zona protegida."],
      pt: ["Famosa pela ponte circular.", "Faz parte de uma área protegida."],
      fr: ["Célèbre pour son pont de forme circulaire.", "Fait partie d'une zone protégée."],
