      es: ["Conocido por las Termas del Arapey.", "Desemboca en el Río Uruguay."],
      pt: ["Conhecido pelas Termas del Arapey.", "Desagua no Río Uruguay."],
      fr: ["Connu pour les Termas del Arapey.", "Se jette dans le Río Uruguay."],
