    description: {
      de: "Ein breiter Bach, der in das Ästuar des Río de la Plata mündet und oft für den Wassersport genutzt wird.",
      hu: "Egy széles patak, amely a Río de la Plata tölcsértorkolatába ömlik, és gyakran használják vízi sportokra.",
      ro: "Un pârâu lat care se varsă în estuarul Río de la Plata și este adesea folosit pentru sporturi nautice.",
      en: "A wide stream that flows into the Río de la Plata estuary and is often used for water sports.",
      es: "Un ancho arroyo que desemboca en el estuario del Río de la Plata y se utiliza a menudo para deportes acuáticos.",
      pt: "Um ribeiro largo que desagua no estuário do Rio da Prata e é frequentemente utilizado para desportos náuticos.",
      fr: "Un large ruisseau qui se jette dans l'estuaire du Río de la Plata et est souvent utilisé pour les sports nautiques.", },
    descriptionAdvanced: {
      de: "Der Arroyo Solís Grande ist ein Bach, der an der Grenze zwischen den Departamentos Canelones und Maldonado im Süden Uruguays verläuft. Er entspringt in der Sierra de las Ánimas im Departamento Lavalleja und fließt etwa 30 Kilometer nach Süden, bevor er im Ferienort Solís in den Río de la Plata mündet. Obwohl er relativ kurz ist, hat der Bach eine bedeutende historische und touristische Relevanz. Sein Name erinnert an Juan Díaz de Solís, den spanischen Entdecker, der 1516 als erster Europäer den Río de la Plata befuhr. Die Mündung des Baches bildet eine malerische Lagune und einen Sandstrand, der bei Einheimischen und Touristen beliebt ist. Die Region ist bekannt für ihre ruhige Atmosphäre, die im Gegensatz zu den belebteren Ferienorten wie Punta del Este steht. Die Eisenbahnbrücke über den Bach, die Ende des 19. Jahrhunderts erbaut wurde, ist ein bemerkenswertes Ingenieurwerk dieser Zeit. Das Einzugsgebiet ist von Wäldern und landwirtschaftlichen Flächen geprägt, die zur landschaftlichen Schönheit beitragen.",
      hu: "Az Arroyo Solís Grande egy patak, amely Canelones és Maldonado megyék határán folyik Uruguay déli részén. Lavalleja megyében, a Sierra de las Ánimas hegységben ered, és körülbelül 30 kilométert tesz meg dél felé, mielőtt a Río de la Platába torkollik Solís üdülőhelyén. Bár viszonylag rövid, a patak jelentős történelmi és turisztikai relevanciával bír. Neve Juan Díaz de Solís spanyol felfedezőnek állít emléket, aki 1516-ban első európaiként hajózott be a Río de la Platára. A patak torkolata festői lagúnát és homokos strandot képez, amely népszerű a helyiek és a turisták körében. A régió nyugodt légköréről ismert, amely ellentétben áll az olyan forgalmasabb üdülőhelyekkel, mint Punta del Este. A patak felett átívelő, 19. század végén épült vasúti híd a kor figyelemre méltó mérnöki alkotása. Vízgyűjtő területét erdők és mezőgazdasági területek jellemzik, amelyek hozzájárulnak a táj szépségéhez.",
      ro: "Arroyo Solís Grande este un pârâu care marchează granița dintre departamentele Canelones și Maldonado, în sudul Uruguayului. Izvorăște din Sierra de las Ánimas în departamentul Lavalleja și curge spre sud pe o distanță de aproximativ 30 de kilometri înainte de a se vărsa în Río de la Plata la stațiunea Solís. Deși este relativ scurt, pârâul are o relevanță istorică și turistică semnificativă. Numele său îl comemorează pe Juan Díaz de Solís, exploratorul spaniol creditat ca fiind primul european care a navigat pe Río de la Plata în 1516. Gura de vărsare a pârâului formează o lagună pitorească și o plajă de nisip, populară printre localnici și turiști. Regiunea este cunoscută pentru atmosfera sa liniștită, în contrast cu stațiunile mai aglomerate precum Punta del Este. Podul de cale ferată peste pârâu, construit la sfârșitul secolului al XIX-lea, este o lucrare de inginerie notabilă a epocii. Bazinul său hidrografic este caracterizat de păduri și terenuri agricole, contribuind la frumusețea peisajului.",
      en: "The Arroyo Solís Grande is a stream that marks the border between the departments of Canelones and Maldonado in southern Uruguay. It originates in the Sierra de las Ánimas in the Lavalleja department and flows south for approximately 30 kilometers before emptying into the Río de la Plata at the resort town of Solís. Although relatively short, the stream has significant historical and touristic relevance. Its name commemorates Juan Díaz de Solís, the Spanish explorer credited as the first European to navigate the Río de la Plata in 1516. The stream's mouth forms a picturesque lagoon and a sandy beach, popular with locals and tourists. The region is known for its tranquil atmosphere, contrasting with busier resorts like Punta del Este. The railway bridge over the stream, built in the late 19th century, is a notable engineering work of its time. Its basin is characterized by forests and agricultural lands, contributing to its scenic beauty.",
      es: "Un ancho arroyo que desemboca en el estuario del Río de la Plata y se utiliza a menudo para deportes acuáticos. El Arroyo Solís Grande se encuentra en el departamento de Maldonado y es un ejemplo notable de la diversidad de Uruguay. La zona es un hábitat importante para numerosas especies de plantas y animales uruguayos. La vegetación natural y el paisaje virgen convierten el lugar en un destino apreciado para el turismo de naturaleza y el ecoturismo. La protección de esta región contribuye decisivamente a la biodiversidad del país. El sitio forma parte del patrimonio nacional de Uruguay y figura en materiales escolares y educativos.",
      pt: "Um ribeiro largo que desagua no estuário do Rio da Prata e é frequentemente utilizado para desportos náuticos. O Arroyo Solís Grande situa-se no departamento de Maldonado e é um exemplo notável da diversidade do Uruguai. A área é um habitat importante para inúmeras espécies de plantas e animais uruguaios. A vegetação natural e a paisagem intocada tornam o local um destino apreciado para o turismo de natureza e ecoturismo. A proteção desta região contribui decisivamente para a biodiversidade do país. O local faz parte do património nacional do Uruguai e é abordado em materiais escolares e educativos.",
      fr: "Un large ruisseau qui se jette dans l'estuaire du Río de la Plata et est souvent utilisé pour les sports nautiques. L'Arroyo Solís Grande est situé dans le département de Maldonado et constitue un exemple remarquable de la diversité de l'Uruguay. La zone est un habitat important pour de nombreuses espèces végétales et animales uruguayennes. La végétation naturelle et le paysage préservé font de ce lieu une destination prisée pour le tourisme de nature et l'écotourisme. La protection de cette région contribue de manière décisive à la biodiversité du pays. Le site fait partie du patrimoine national de l'Uruguay et est thatisé dans les supports scolaires et éducatifs.",
    },
